-- The schema after every migration in authz/services/policy/migrations, generated by tools/db-schema.
-- Read it; don't edit it: change the schema with a new migration, then run tools/db-schema.

CREATE TABLE public.break_glass_events (
    id uuid NOT NULL,
    key_id text NOT NULL,
    nonce text NOT NULL,
    reason text NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    replaced_version bigint,
    restored_version bigint NOT NULL,
    new_bundle_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.enforcement_mode_changes (
    id uuid NOT NULL,
    scope text NOT NULL,
    mode text NOT NULL,
    changed_by text NOT NULL,
    changed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT enforcement_mode_changes_mode_check CHECK ((mode = ANY (ARRAY['monitor'::text, 'enforce'::text])))
);

CREATE TABLE public.policy_bundles (
    id uuid NOT NULL,
    version bigint NOT NULL,
    schema_src text NOT NULL,
    policies_src text NOT NULL,
    status text NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    published_by text,
    published_at timestamp with time zone,
    signature bytea,
    signing_key_id text,
    CONSTRAINT policy_bundles_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'superseded'::text])))
);

ALTER TABLE public.policy_bundles ALTER COLUMN version ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.policy_bundles_version_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

ALTER TABLE ONLY public.break_glass_events
    ADD CONSTRAINT break_glass_events_nonce_key UNIQUE (nonce);

ALTER TABLE ONLY public.break_glass_events
    ADD CONSTRAINT break_glass_events_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.enforcement_mode_changes
    ADD CONSTRAINT enforcement_mode_changes_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.policy_bundles
    ADD CONSTRAINT policy_bundles_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.policy_bundles
    ADD CONSTRAINT policy_bundles_version_key UNIQUE (version);

CREATE INDEX enforcement_mode_changes_by_scope ON public.enforcement_mode_changes USING btree (scope, changed_at DESC);

CREATE UNIQUE INDEX policy_bundles_one_active ON public.policy_bundles USING btree ((true)) WHERE (status = 'active'::text);

ALTER TABLE ONLY public.break_glass_events
    ADD CONSTRAINT break_glass_events_new_bundle_id_fkey FOREIGN KEY (new_bundle_id) REFERENCES public.policy_bundles(id);

